ab={'1':np.ones_like(A),'A':A,'A2':A**2,'sqrtA':np.sqrt(A),'1/A':1/A,'1/(1+A)':1/(1+A),'exp(-A)':np.exp(-A),'logA':np.log(A)}
cols={kt+'*'+ka:vt*va for kt,vt in tb.items() for ka,va in ab.items()}
names=list(cols)
out=[]
